#!/usr/bin/env bash
# End-to-end regression suite for the Ilm o Irfan Edge Functions.
#
# Covers the happy paths plus the regressions that matter: the premium gate, the
# publish gate against Storage, partial-write merge semantics, method contracts,
# pagination limits, audit attribution, and an RLS suite that asserts the rules
# a breach would violate.
#
# Assumes: npx supabase start + db reset already run, functions serve running.
set -u

B=http://127.0.0.1:54321/functions/v1

# The local keys used to be pasted in here. They are demo keys, not secrets, but
# they are regenerated by newer CLI versions, so a pinned copy eventually fails
# every request with a 401 that looks like a broken endpoint. Ask the running
# stack instead, and let the environment override for a non-default setup.
if [ -z "${ANON:-}" ] || [ -z "${SERVICE:-}" ]; then
  eval "$(npx --no-install supabase status -o env 2>/dev/null)" || true
  ANON="${ANON:-${ANON_KEY:-}}"
  SERVICE="${SERVICE:-${SERVICE_ROLE_KEY:-}}"
fi

if [ -z "${ANON:-}" ] || [ -z "${SERVICE:-}" ]; then
  echo "Could not read local keys. Run 'npx supabase start' first, or export ANON and SERVICE." >&2
  exit 1
fi

DB=supabase_db_ilm-o-irfan
BOOK=aaaaaaaa-0000-0000-0000-000000000001
FREE=aaaaaaaa-0000-0000-0000-000000000002
DRAFT=aaaaaaaa-0000-0000-0000-000000000003
MISSING=aaaaaaaa-0000-0000-0000-000000000004

PASS=0; FAIL=0
ok(){ PASS=$((PASS+1)); printf '  \033[32mPASS\033[0m %s\n' "$1"; }
no(){ FAIL=$((FAIL+1)); printf '  \033[31mFAIL\033[0m %s\n     expected: %s\n     actual:   %s\n' "$1" "$2" "$3"; }
is(){ [ "$2" = "$3" ] && ok "$1" || no "$1" "$3" "$2"; }
has(){ case "$2" in *"$3"*) ok "$1";; *) no "$1" "contains '$3'" "${2:0:150}";; esac; }
code(){ curl -s -o /dev/null -w '%{http_code}' "$@"; }

psqlq(){ docker exec -i "$DB" psql -U postgres -d postgres -q -t -A -c "$1"; }

echo "== seeding =="
docker exec -i "$DB" psql -U postgres -d postgres -q >/dev/null <<'SQL'
-- Clear any previous fixtures first. `on conflict (slug) do nothing` is not
-- enough on its own: a leftover row holding one of these ids under a different
-- slug raises a primary key violation that aborts the whole INSERT, leaving the
-- suite to run against an empty catalog and fail for the wrong reason.
delete from public.books
 where id in ('aaaaaaaa-0000-0000-0000-000000000001',
              'aaaaaaaa-0000-0000-0000-000000000002',
              'aaaaaaaa-0000-0000-0000-000000000003',
              'aaaaaaaa-0000-0000-0000-000000000004')
    or slug in ('ihya','masnavi','draft','missing-pdf');
delete from public.authors
 where id in ('11111111-1111-1111-1111-111111111111',
              '22222222-2222-2222-2222-222222222222')
    or slug in ('imam-ghazali','rumi');

insert into public.authors (id, slug, name) values
  ('11111111-1111-1111-1111-111111111111','imam-ghazali','Imam Al Ghazali'),
  ('22222222-2222-2222-2222-222222222222','rumi','Jalaluddin Rumi') on conflict (slug) do nothing;
insert into public.books (id, slug, title, description, author_id, genre, tag, tags, pdf_path, is_published, published_at, is_premium) values
  ('aaaaaaaa-0000-0000-0000-000000000001','ihya','Ihya Ulum al-Din','A revival of the religious sciences.','11111111-1111-1111-1111-111111111111','Spirituality','Classic', array['fiqh','ethics'], 'pdfs/ihya.pdf', true, now(), true),
  ('aaaaaaaa-0000-0000-0000-000000000002','masnavi','The Masnavi','Poetry of the soul and divine love.','22222222-2222-2222-2222-222222222222','Poetry','Featured', array['sufism'], 'pdfs/masnavi.pdf', true, now(), false),
  ('aaaaaaaa-0000-0000-0000-000000000003','draft','Unpublished Draft','Hidden work in progress.','22222222-2222-2222-2222-222222222222','Poetry',null, array[]::text[], null, false, null, false),
  ('aaaaaaaa-0000-0000-0000-000000000004','missing-pdf','Missing Storage Object','Published free book whose object was never uploaded.','22222222-2222-2222-2222-222222222222','Poetry',null, array[]::text[], 'pdfs/does-not-exist-e2e.pdf', true, now(), false) on conflict (slug) do nothing;
SQL
printf '%%PDF-1.4\ntrailer<</Root 1 0 R>>\n%%%%EOF\n' > /tmp/e2e.pdf
curl -s -X POST "http://127.0.0.1:54321/storage/v1/object/pdfs/ihya.pdf" -H "Authorization: Bearer $SERVICE" -H "Content-Type: application/pdf" --data-binary @/tmp/e2e.pdf >/dev/null
curl -s -X POST "http://127.0.0.1:54321/storage/v1/object/pdfs/masnavi.pdf" -H "Authorization: Bearer $SERVICE" -H "Content-Type: application/pdf" --data-binary @/tmp/e2e.pdf >/dev/null

EMAIL="e2e$(date +%s)@test.local"
TOKEN=$(curl -s -X POST "http://127.0.0.1:54321/auth/v1/signup" -H "apikey: $ANON" -H "Content-Type: application/json" \
  -d "{\"email\":\"$EMAIL\",\"password\":\"Password123!\"}" | sed -n 's/.*"access_token":"\([^"]*\)".*/\1/p')
[ -n "$TOKEN" ] || { echo "could not create user"; exit 1; }
A=(-H "Authorization: Bearer $TOKEN" -H "Content-Type: application/json")
P=(-H "Authorization: Bearer $ANON")

echo
echo "== public catalog =="
is "home-feed 200"        "$(code "$B/home-feed" "${P[@]}")" 200
has "home-feed carousel"  "$(curl -s "$B/home-feed" "${P[@]}")" '"carousel"'
is "carousel-list 200"    "$(code "$B/carousel-list" "${P[@]}")" 200
is "trending-weekly 200"  "$(code "$B/trending-weekly?limit=5" "${P[@]}")" 200
has "trending weekStart"  "$(curl -s "$B/trending-weekly?limit=5" "${P[@]}")" '"weekStart"'
is "books-list 200"       "$(code "$B/books-list" "${P[@]}")" 200
is "books-list language filter 200" "$(code "$B/books-list?language=english&page=1&pageSize=5" "${P[@]}")" 200
is "books-list sort rating 200" "$(code "$B/books-list?sort=rating&page=1&pageSize=5" "${P[@]}")" 200
is "book-detail 200"      "$(code "$B/book-detail?id=$BOOK" "${P[@]}")" 200
is "categories-list 200"  "$(code "$B/categories-list" "${P[@]}")" 200
is "collections-list 200" "$(code "$B/collections-list" "${P[@]}")" 200
is "collection-books needs id" "$(code "$B/collection-books" "${P[@]}")" 400
is "collection-books by slug" "$(code "$B/collection-books?slug=home-hero" "${P[@]}")" 200
has "books-list coverUrl" "$(curl -s "$B/books-list" "${P[@]}")" '"coverUrl"'
has "book-detail no pdf_path" "$(curl -s "$B/book-detail?id=$BOOK" "${P[@]}")" '"coverUrl"'
case "$(curl -s "$B/book-detail?id=$BOOK" "${P[@]}")" in *pdf_path*) no "pdf_path not leaked" "absent" "present";; *) ok "pdf_path not leaked";; esac
is "plans-list 200"       "$(code "$B/plans-list" "${P[@]}")" 200
is "book-detail bad uuid 400" "$(code "$B/book-detail?id=nope" "${P[@]}")" 400
is "book-detail draft 404"    "$(code "$B/book-detail?id=$DRAFT" "${P[@]}")" 404
has "books-list has no tsvector" "$(curl -s "$B/books-list" "${P[@]}")" '"published_at"'
case "$(curl -s "$B/books-list" "${P[@]}")" in *search_vector*) no "tsvector not leaked" "absent" "present";; *) ok "tsvector not leaked";; esac

# Category filter: spirituality is seeded; unknown slug 404s.
is "books-list bad category 404" "$(code "$B/books-list?category=not-a-real-category" "${P[@]}")" 404
is "books-list category slug" "$(code "$B/books-list?category=spirituality" "${P[@]}")" 200

echo
echo "== search =="
has "by author"      "$(curl -s "$B/books-search?q=Ghazali" "${P[@]}")" 'Ihya'
has "by title"       "$(curl -s "$B/books-search?q=Masnavi" "${P[@]}")" 'Masnavi'
has "by description" "$(curl -s "$B/books-search?q=divine%20love" "${P[@]}")" 'Masnavi'
has "by tag"         "$(curl -s "$B/books-search?q=sufism" "${P[@]}")" 'Masnavi'
has "draft hidden"   "$(curl -s "$B/books-search?q=Hidden" "${P[@]}")" '"totalCount":0'
is  "punctuation 200" "$(code "$B/books-search?q=a%2Cb%28c%29%26--%3B" "${P[@]}")" 200
has "empty query"    "$(curl -s "$B/books-search?q=" "${P[@]}")" '"totalCount":0'

echo
echo "== pagination =="
has "page1 hasNext"  "$(curl -s "$B/books-list?page=1&pageSize=1" "${P[@]}")" '"hasNextPage":true'
has "page2 hasPrev"  "$(curl -s "$B/books-list?page=2&pageSize=1" "${P[@]}")" '"hasPreviousPage":true'
has "pageSize clamp" "$(curl -s "$B/books-list?pageSize=9999" "${P[@]}")" '"pageSize":100'
has "garbage page"   "$(curl -s "$B/books-list?page=abc" "${P[@]}")" '"page":1'

echo
echo "== auth gate (no token) =="
for e in profile-read reading-progress wishlist-list downloads-list highlights-list library-overview entitlements-status admin-books get-signed-pdf; do
  is "$e 401" "$(code -X POST "$B/$e" -H 'Content-Type: application/json' -d '{}')" 401
done
is "recommendations 401" "$(code "$B/recommendations" "${P[@]}")" 401

echo
echo "== profile partial update (data-loss regression) =="
curl -s -X PUT "$B/profile-update" "${A[@]}" -d '{"full_name":"Full Name","phone":"+92 300 1234567","city":"Lahore","country":"Pakistan","address_line1":"12 Mall Road"}' >/dev/null
R=$(curl -s -X PUT "$B/profile-update" "${A[@]}" -d '{"full_name":"Only Name Changed"}')
has "name updated"    "$R" '"full_name":"Only Name Changed"'
has "phone survived"  "$R" '"phone":"+92 300 1234567"'
has "city survived"   "$R" '"city":"Lahore"'
has "address survived" "$R" '"address_line1":"12 Mall Road"'
is  "empty body 400"  "$(code -X PUT "$B/profile-update" "${A[@]}" -d '{}')" 400
has "explicit null clears" "$(curl -s -X PUT "$B/profile-update" "${A[@]}" -d '{"city":null}')" '"city":null'

echo
echo "== reading progress scale =="
has "progress 1 = finished" "$(curl -s -X POST "$B/reading-progress" "${A[@]}" -d "{\"book_id\":\"$BOOK\",\"progress\":1}")" '"progress":1'
has "percent 1 = 1%"        "$(curl -s -X POST "$B/reading-progress" "${A[@]}" -d "{\"book_id\":\"$BOOK\",\"progress_percent\":1}")" '"progress":0.01'
is  "out of range 400"      "$(code -X POST "$B/reading-progress" "${A[@]}" -d "{\"book_id\":\"$BOOK\",\"progress\":55}")" 400
is  "both scales 400"       "$(code -X POST "$B/reading-progress" "${A[@]}" -d "{\"book_id\":\"$BOOK\",\"progress\":0.5,\"progress_percent\":50}")" 400
is  "bad uuid 400"          "$(code -X POST "$B/reading-progress" "${A[@]}" -d '{"book_id":"nope"}')" 400
is  "missing book 404"      "$(code -X POST "$B/reading-progress" "${A[@]}" -d '{"book_id":"99999999-9999-9999-9999-999999999999"}')" 404

echo
echo "== wishlist =="
curl -s -X POST "$B/wishlist-toggle" "${A[@]}" -d "{\"book_id\":\"$BOOK\"}" >/dev/null
has "toggle removes" "$(curl -s -X POST "$B/wishlist-toggle" "${A[@]}" -d "{\"book_id\":\"$BOOK\"}")" '"wishlisted":false'
RACE=""
for i in 1 2 3 4 5 6 7 8; do RACE="$RACE$(code -X POST "$B/wishlist-toggle" "${A[@]}" -d "{\"book_id\":\"$BOOK\"}" &)"; done; wait
case "$RACE" in *500*) no "8 concurrent toggles no 500" "no 500s" "$RACE";; *) ok "8 concurrent toggles no 500";; esac
is "missing book 404" "$(code -X POST "$B/wishlist-toggle" "${A[@]}" -d '{"book_id":"99999999-9999-9999-9999-999999999999"}')" 404

echo
echo "== downloads / highlights =="
is "downloads-create 200" "$(code -X POST "$B/downloads-create" "${A[@]}" -d "{\"book_id\":\"$BOOK\",\"file_size_bytes\":999}")" 200
is "bad status 400"       "$(code -X POST "$B/downloads-create" "${A[@]}" -d "{\"book_id\":\"$BOOK\",\"status\":\"bogus\"}")" 400
HID=$(curl -s -X POST "$B/highlights-upsert" "${A[@]}" -d "{\"book_id\":\"$BOOK\",\"page_number\":12,\"text_excerpt\":\"excerpt text\",\"color\":\"amber\"}" | sed -n 's/.*"id":"\([^"]*\)".*/\1/p')
R=$(curl -s -X POST "$B/highlights-upsert" "${A[@]}" -d "{\"id\":\"$HID\",\"note\":\"my note\"}")
has "note updated"     "$R" '"note":"my note"'
has "excerpt survived" "$R" '"text_excerpt":"excerpt text"'
has "color survived"   "$R" '"color":"amber"'

echo
echo "== paywall =="
psqlq "delete from public.entitlements where user_id=(select id from public.profiles where email='$EMAIL');" >/dev/null
# The catalogue is subscription-only. $FREE is seeded with is_premium=false on
# purpose: it proves the flag no longer opens the gate. If this assertion ever
# flips back to expecting a signedUrl, the paywall has a hole in it.
has "is_premium=false book without entitlement -> PREMIUM_REQUIRED" \
  "$(curl -s -X POST "$B/get-signed-pdf" "${A[@]}" -d "{\"bookId\":\"$FREE\"}")" 'PREMIUM_REQUIRED'
has "premium book without entitlement -> PREMIUM_REQUIRED" "$(curl -s -X POST "$B/get-signed-pdf" "${A[@]}" -d "{\"bookId\":\"$BOOK\"}")" 'PREMIUM_REQUIRED'
psqlq "insert into public.entitlements (user_id,status,store,starts_at,expires_at) select id,'active','stripe',now(),now()+interval '30 days' from public.profiles where email='$EMAIL' on conflict (user_id) do update set status='active',expires_at=now()+interval '30 days';" >/dev/null
R=$(curl -s -X POST "$B/get-signed-pdf" "${A[@]}" -d "{\"bookId\":\"$BOOK\"}")
has "premium book with entitlement -> signedUrl" "$R" 'signedUrl'
has "is_premium=false book with entitlement -> signedUrl" \
  "$(curl -s -X POST "$B/get-signed-pdf" "${A[@]}" -d "{\"bookId\":\"$FREE\"}")" 'signedUrl'
# Missing object is checked after the gate, so it needs the entitlement first.
has "published book missing object -> PDF_NOT_IN_STORAGE" \
  "$(curl -s -X POST "$B/get-signed-pdf" "${A[@]}" -d "{\"bookId\":\"$MISSING\"}")" 'PDF_NOT_IN_STORAGE'
URL=$(echo "$R" | sed -n 's/.*"signedUrl":"\([^"]*\)".*/\1/p' | sed 's|http://kong:8000|http://127.0.0.1:54321|')
is "signed url serves pdf 200" "$(code "$URL")" 200
is "unsigned object denied"    "$(code 'http://127.0.0.1:54321/storage/v1/object/pdfs/ihya.pdf')" 400
is "deprecated alias 410"      "$(code -X POST "$B/signed-pdf" -H 'Content-Type: application/json' -d '{}')" 410

echo
echo "== subscription lifecycle: the access rule =="
# 'expired' is the only status that denies on its own. Everything else grants
# right up to expires_at. The gate used to test status='active' and locked out
# trials and cancelled-but-paid-for months; these assertions are why.
ent() { psqlq "update public.entitlements set status='$1', expires_at=$2 where user_id=(select id from public.profiles where email='$EMAIL');" >/dev/null; }
gate() { curl -s -X POST "$B/get-signed-pdf" "${A[@]}" -d "{\"bookId\":\"$BOOK\"}"; }

ent 'trial' "now()+interval '1 day'"
has "trial -> served"                    "$(gate)" 'signedUrl'
ent 'cancelled' "now()+interval '1 day'"
has "cancelled but paid through -> served" "$(gate)" 'signedUrl'
ent 'grace' "now()+interval '1 day'"
has "grace -> served"                    "$(gate)" 'signedUrl'
ent 'billing_issue' "now()+interval '1 day'"
has "billing issue inside paid period -> served" "$(gate)" 'signedUrl'
ent 'cancelled' "now()-interval '1 second'"
has "cancelled and past expiry -> PREMIUM_REQUIRED" "$(gate)" 'PREMIUM_REQUIRED'
ent 'expired' "now()+interval '30 days'"
has "explicitly expired beats a future date (refund) -> PREMIUM_REQUIRED" "$(gate)" 'PREMIUM_REQUIRED'

echo
echo "== subscription lifecycle: expiry is enforced before the sweep runs =="
# The sweep is only what makes expiry *pushable*. Access must already be gone
# the instant now() passes expires_at, with no cron run in between.
ent 'active' "now()-interval '1 second'"
is "lapsed one second ago, row still says active" \
  "$(psqlq "select status from public.entitlements where user_id=(select id from public.profiles where email='$EMAIL');" | tr -d ' ')" "active"
has "...but the gate already refuses" "$(gate)" 'PREMIUM_REQUIRED'
has "...and entitlements-status agrees" \
  "$(curl -s "$B/entitlements-status" "${A[@]}")" '"canAccessPremium":false'

echo
echo "== subscription lifecycle: the sweep and the broadcast =="
psqlq "delete from realtime.messages;" >/dev/null
is "sweep flips exactly the lapsed row" "$(psqlq "select public.expire_lapsed_entitlements();" | tr -d ' ')" "1"
is "status is now expired" \
  "$(psqlq "select status from public.entitlements where user_id=(select id from public.profiles where email='$EMAIL');" | tr -d ' ')" "expired"
is "sweep is idempotent" "$(psqlq "select public.expire_lapsed_entitlements();" | tr -d ' ')" "0"
is "one broadcast, on the reader's own private topic" \
  "$(psqlq "select count(*) from realtime.messages where topic='entitlement:'||(select id from public.profiles where email='$EMAIL') and private and extension='broadcast';" | tr -d ' ')" "1"
has "broadcast carries the lock, not a row diff" \
  "$(psqlq "select payload::text from realtime.messages limit 1;")" '"canAccessPremium": false'
has "broadcast names the reason" \
  "$(psqlq "select payload::text from realtime.messages limit 1;")" '"reason": "expired"'
# A device must not be able to talk itself back in.
case "$(psqlq "select payload::text from realtime.messages limit 1;")" in
  *raw_event*|*store*) no "broadcast does not leak billing internals" "absent" "present";;
  *) ok "broadcast does not leak billing internals";;
esac

# Renewal after the sweep already locked them: the row must move again, and
# the sweep must not have poisoned the webhook ordering guard.
psqlq "delete from realtime.messages;" >/dev/null
ent 'active' "now()+interval '30 days'"
is "renewal broadcasts an unlock" \
  "$(psqlq "select count(*) from realtime.messages;" | tr -d ' ')" "1"
has "unlock says access is back" \
  "$(psqlq "select payload::text from realtime.messages limit 1;")" '"canAccessPremium": true'
has "renewal restores the gate" "$(gate)" 'signedUrl'
# Noise must not wake every device the reader owns.
psqlq "delete from realtime.messages;" >/dev/null
psqlq "update public.entitlements set raw_event='{\"noise\":true}'::jsonb where user_id=(select id from public.profiles where email='$EMAIL');" >/dev/null
is "an irrelevant write broadcasts nothing" "$(psqlq "select count(*) from realtime.messages;" | tr -d ' ')" "0"
# A lifetime / promotional comp has no end date and must never be swept.
ent 'active' 'null'
is "lifetime comp is never swept" "$(psqlq "select public.expire_lapsed_entitlements();" | tr -d ' ')" "0"
has "lifetime comp still reads" "$(gate)" 'signedUrl'

echo
echo "== subscription lifecycle: what the app is told =="
ent 'active' "now()+interval '30 days'"
ES=$(curl -s "$B/entitlements-status" "${A[@]}")
has "canAccessPremium"   "$ES" '"canAccessPremium":true'
has "expiresAt"          "$ES" '"expiresAt"'
has "secondsRemaining"   "$ES" '"secondsRemaining"'
has "reason"             "$ES" '"reason":"active"'
has "serverTime for clock-skew correction" "$ES" '"serverTime"'
has "the channel to subscribe to" "$ES" '"channel":"entitlement:'
has "marked private"     "$ES" '"private":true'

echo
echo "== recommendations =="
is "recommendations 200" "$(code "$B/recommendations?limit=10" "${A[@]}")" 200
has "recommendations envelope" "$(curl -s "$B/recommendations?limit=10" "${A[@]}")" '"isPersonalized"'

# A signed URL must not outlive the subscription. 40 seconds left, 300s default.
# Asserted as a range, not an exact number: the value depends on how long the
# request itself took, and a flaky test on a paywall gets muted rather than fixed.
ent 'active' "now()+interval '40 seconds'"
TTL=$(gate | sed -n 's/.*"expiresIn":\([0-9]*\).*/\1/p')
if [ -n "$TTL" ] && [ "$TTL" -ge 15 ] && [ "$TTL" -le 40 ]; then
  ok "signed url clamped to the remaining subscription (${TTL}s <= 40s)"
else
  no "signed url clamped to the remaining subscription" "15-40" "$TTL"
fi
ent 'active' "now()+interval '30 days'"
has "plenty of time left -> full default TTL" "$(gate)" '"expiresIn":300'
has "open re-anchors the client countdown" "$(gate)" '"access"'

echo
echo "== revenuecat webhook auth =="
# Local serve may omit REVENUECAT_WEBHOOK_AUTH → 500 WEBHOOK_CONFIG_ERROR; wrong
# secret when configured → 401 WEBHOOK_AUTH_FAILED. Both prove the gate runs.
WH=$(curl -s -X POST "$B/revenuecat-webhook" -H 'Content-Type: application/json' \
  -H 'Authorization: Bearer WRONG_E2E_SECRET' \
  -d '{"event":{"id":"00000000-0000-0000-0000-000000000099"}}')
WH_CODE=$(code -X POST "$B/revenuecat-webhook" -H 'Content-Type: application/json' \
  -H 'Authorization: Bearer WRONG_E2E_SECRET' -d '{}')
case "$WH" in
  *WEBHOOK_AUTH_FAILED*|*WEBHOOK_CONFIG_ERROR*) ok "webhook rejects bad/missing secret body";;
  *) no "webhook rejects bad/missing secret body" "WEBHOOK_AUTH_FAILED|WEBHOOK_CONFIG_ERROR" "${WH:0:150}";;
esac
case "$WH_CODE" in
  401|500) ok "webhook auth gate HTTP $WH_CODE";;
  *) no "webhook auth gate HTTP" "401|500" "$WH_CODE";;
esac

echo
echo "== revenuecat webhook apply (APP_STORE + PLAY_STORE) =="
# Success paths need the same Authorization value the local functions serve process
# was started with. Export REVENUECAT_WEBHOOK_AUTH before `supabase functions serve`.
RC_AUTH="${REVENUECAT_WEBHOOK_AUTH:-}"
UID=$(psqlq "select id from public.profiles where email='$EMAIL';" | tr -d ' ')
NOW_MS=$(($(date +%s) * 1000))
EXP_MS=$((NOW_MS + 30 * 24 * 60 * 60 * 1000))
if [ -z "$RC_AUTH" ] || [ -z "$UID" ]; then
  ok "webhook apply skipped (set REVENUECAT_WEBHOOK_AUTH to enable; need e2e user)"
else
  # Ensure seed plan product id is present for product_id lookup.
  psqlq "update public.plans set revenuecat_product_id='premium_monthly' where code='premium_monthly';" >/dev/null
  psqlq "delete from public.entitlements where user_id='$UID';" >/dev/null

  APP_EVENT=aaaaaaaa-e2e0-4000-8000-000000000001
  PLAY_EVENT=aaaaaaaa-e2e0-4000-8000-000000000002
  psqlq "delete from public.revenuecat_events where id in ('$APP_EVENT','$PLAY_EVENT');" >/dev/null

  APP_BODY=$(printf '{"event":{"id":"%s","type":"INITIAL_PURCHASE","app_user_id":"%s","entitlement_ids":["premium"],"product_id":"premium_monthly","store":"APP_STORE","purchased_at_ms":%s,"expiration_at_ms":%s,"event_timestamp_ms":%s}}' \
    "$APP_EVENT" "$UID" "$NOW_MS" "$EXP_MS" "$NOW_MS")
  APP_RES=$(curl -s -X POST "$B/revenuecat-webhook" -H "Content-Type: application/json" \
    -H "Authorization: $RC_AUTH" -d "$APP_BODY")
  has "APP_STORE initial purchase applied" "$APP_RES" '"applied":true'
  has "APP_STORE maps store" "$APP_RES" '"store":"app_store"'
  is "APP_STORE entitlement active" \
    "$(psqlq "select status from public.entitlements where user_id='$UID';" | tr -d ' ')" "active"
  is "APP_STORE store column" \
    "$(psqlq "select store from public.entitlements where user_id='$UID';" | tr -d ' ')" "app_store"

  DUP=$(curl -s -X POST "$B/revenuecat-webhook" -H "Content-Type: application/json" \
    -H "Authorization: $RC_AUTH" -d "$APP_BODY")
  has "APP_STORE duplicate is idempotent" "$DUP" '"duplicate":true'

  PLAY_BODY=$(printf '{"event":{"id":"%s","type":"INITIAL_PURCHASE","app_user_id":"%s","entitlement_ids":["premium"],"product_id":"premium_monthly","store":"PLAY_STORE","purchased_at_ms":%s,"expiration_at_ms":%s,"event_timestamp_ms":%s}}' \
    "$PLAY_EVENT" "$UID" "$((NOW_MS + 1000))" "$EXP_MS" "$((NOW_MS + 1000))")
  PLAY_RES=$(curl -s -X POST "$B/revenuecat-webhook" -H "Content-Type: application/json" \
    -H "Authorization: $RC_AUTH" -d "$PLAY_BODY")
  has "PLAY_STORE initial purchase applied" "$PLAY_RES" '"applied":true'
  has "PLAY_STORE maps store" "$PLAY_RES" '"store":"play_store"'
  is "PLAY_STORE store column" \
    "$(psqlq "select store from public.entitlements where user_id='$UID';" | tr -d ' ')" "play_store"

  # Unknown SKU still falls back to premium_monthly so a mistyped product id does not drop access.
  UNK_EVENT=aaaaaaaa-e2e0-4000-8000-000000000003
  psqlq "delete from public.revenuecat_events where id='$UNK_EVENT';" >/dev/null
  UNK_BODY=$(printf '{"event":{"id":"%s","type":"INITIAL_PURCHASE","app_user_id":"%s","entitlement_ids":["premium"],"product_id":"unknown.sku.not.in.plans","store":"APP_STORE","purchased_at_ms":%s,"expiration_at_ms":%s,"event_timestamp_ms":%s}}' \
    "$UNK_EVENT" "$UID" "$((NOW_MS + 2000))" "$EXP_MS" "$((NOW_MS + 2000))")
  UNK_RES=$(curl -s -X POST "$B/revenuecat-webhook" -H "Content-Type: application/json" \
    -H "Authorization: $RC_AUTH" -d "$UNK_BODY")
  has "unknown product_id still applies via premium_monthly fallback" "$UNK_RES" '"applied":true'
  has "fallback still returns planId" "$UNK_RES" '"planId"'
fi

echo
echo "== admin gate =="
for e in admin-books admin-users admin-analytics admin-settings; do
  is "$e forbidden for user" "$(code "$B/$e" "${A[@]}")" 403
done
psqlq "update public.profiles set role='admin' where email='$EMAIL';" >/dev/null
for e in admin-books admin-users admin-categories admin-collections admin-settings; do
  is "$e 200 for admin" "$(code "$B/$e" "${A[@]}")" 200
done
is "admin-analytics 200" "$(code "$B/admin-analytics?days=30" "${A[@]}")" 200
has "analytics payload"  "$(curl -s "$B/admin-analytics?days=30" "${A[@]}")" 'top_books'
is "admin-storage-audit 200" "$(code "$B/admin-storage-audit" "${A[@]}")" 200
has "storage audit payload" "$(curl -s "$B/admin-storage-audit" "${A[@]}")" 'broken'

echo
echo "== paywall: admin bypass (runs here because it needs the admin role) =="
# Admins hold no subscription and must still be served, drafts included. The
# app relies on this for previews, so it is the one branch that stays open.
psqlq "delete from public.entitlements where user_id=(select id from public.profiles where email='$EMAIL');" >/dev/null
has "admin without entitlement -> signedUrl" \
  "$(curl -s -X POST "$B/get-signed-pdf" "${A[@]}" -d "{\"bookId\":\"$BOOK\"}")" 'signedUrl'
# Point the draft at a real object so the draft case reaches the gate rather
# than tripping over a missing pdf_path.
psqlq "update public.books set pdf_path='pdfs/masnavi.pdf' where id='$DRAFT';" >/dev/null
has "admin without entitlement -> unpublished draft signedUrl" \
  "$(curl -s -X POST "$B/get-signed-pdf" "${A[@]}" -d "{\"bookId\":\"$DRAFT\"}")" 'signedUrl'
psqlq "update public.profiles set role='user' where email='$EMAIL';" >/dev/null
is "non-admin draft -> 404 (existence not revealed)" \
  "$(code -X POST "$B/get-signed-pdf" "${A[@]}" -d "{\"bookId\":\"$DRAFT\"}")" 404
psqlq "update public.profiles set role='admin' where email='$EMAIL';" >/dev/null
# Put the draft back: the publish-gate section below needs it with no pdf_path.
psqlq "update public.books set pdf_path=null where id='$DRAFT';" >/dev/null

echo
echo "== admin settings partial patch =="
curl -s -X PATCH "$B/admin-settings" "${A[@]}" -d '{"maintenance_message":"msg","signup_enabled":true}' >/dev/null
R=$(curl -s -X PATCH "$B/admin-settings" "${A[@]}" -d '{"maintenance_mode":true}')
has "boolean set"       "$R" '"maintenance_mode":true'
has "message survived"  "$R" '"maintenance_message":"msg"'
has "signup survived"   "$R" '"signup_enabled":true'
is  "bad type 400"      "$(code -X PATCH "$B/admin-settings" "${A[@]}" -d '{"signup_enabled":"maybe"}')" 400
is  "empty patch 400"   "$(code -X PATCH "$B/admin-settings" "${A[@]}" -d '{}')" 400

echo
echo "== admin book update =="
has "partial edit"  "$(curl -s -X PATCH "$B/admin-book-update" "${A[@]}" -d "{\"id\":\"$DRAFT\",\"genre\":\"Classical\"}")" '"description":"Hidden work in progress."'
is  "bad price 400" "$(code -X PATCH "$B/admin-book-update" "${A[@]}" -d "{\"id\":\"$DRAFT\",\"price_cents\":-5}")" 400
is  "unknown 404"   "$(code -X PATCH "$B/admin-book-update" "${A[@]}" -d '{"id":"99999999-9999-9999-9999-999999999999","genre":"x"}')" 404
is  "no fields 400" "$(code -X PATCH "$B/admin-book-update" "${A[@]}" -d "{\"id\":\"$DRAFT\"}")" 400

echo
echo "== new books default to premium =="
# The catalogue is subscription-only. A book created without an explicit flag
# must not land free - that is how the hole reopens quietly.
NEWB=$(curl -s -X POST "$B/admin-book-create" "${A[@]}" -d "{\"title\":\"E2E Premium Default\",\"authorId\":\"11111111-1111-1111-1111-111111111111\"}")
has "is_premium omitted -> true" "$NEWB" '"is_premium":true'
# An admin can still mark a deliberate free sampler; access does not depend on it.
has "is_premium false honoured when explicit" \
  "$(curl -s -X POST "$B/admin-book-create" "${A[@]}" -d "{\"title\":\"E2E Explicit Free\",\"authorId\":\"11111111-1111-1111-1111-111111111111\",\"is_premium\":false}")" '"is_premium":false'
psqlq "delete from public.books where slug in ('e2e-premium-default','e2e-explicit-free');" >/dev/null

echo
echo "== publish gate (storage-aware) =="
# DRAFT has no pdf_path at all.
has "publish without pdf_path refused" \
  "$(curl -s -X PATCH "$B/admin-book-update" "${A[@]}" -d "{\"id\":\"$DRAFT\",\"is_published\":true}")" 'PDF_PATH_MISSING'
# A path no object backs: the column would accept it, Storage does not.
has "publish with missing object refused" \
  "$(curl -s -X PATCH "$B/admin-book-update" "${A[@]}" -d "{\"id\":\"$DRAFT\",\"is_published\":true,\"pdf_path\":\"pdfs/does-not-exist.pdf\"}")" 'PDF_NOT_IN_STORAGE'
is "draft is still unpublished" "$(code "$B/book-detail?id=$DRAFT" "${P[@]}")" 404
# Point it at a real object and it goes live.
has "publish with a real object succeeds" \
  "$(curl -s -X PATCH "$B/admin-book-update" "${A[@]}" -d "{\"id\":\"$DRAFT\",\"is_published\":true,\"pdf_path\":\"pdfs/masnavi.pdf\"}")" '"is_published":true'
is "published draft now readable" "$(code "$B/book-detail?id=$DRAFT" "${P[@]}")" 200
curl -s -X PATCH "$B/admin-book-update" "${A[@]}" -d "{\"id\":\"$DRAFT\",\"is_published\":false}" >/dev/null

echo
echo "== reading progress merge (partial write) =="
curl -s -X POST "$B/reading-progress" "${A[@]}" \
  -d "{\"book_id\":\"$FREE\",\"current_page\":42,\"total_pages\":310,\"chapter_label\":\"Chapter 3\",\"progress\":0.13}" >/dev/null
R=$(curl -s -X POST "$B/reading-progress" "${A[@]}" -d "{\"book_id\":\"$FREE\",\"progress\":0.2}")
has "progress updated"      "$R" '"progress":0.2'
has "current_page survived" "$R" '"current_page":42'
has "total_pages survived"  "$R" '"total_pages":310'
has "chapter survived"      "$R" '"chapter_label":"Chapter 3"'
has "empty string clears chapter" \
  "$(curl -s -X POST "$B/reading-progress" "${A[@]}" -d "{\"book_id\":\"$FREE\",\"chapter_label\":\"\"}")" '"chapter_label":null'
is "page past total_pages 400" \
  "$(code -X POST "$B/reading-progress" "${A[@]}" -d "{\"book_id\":\"$FREE\",\"current_page\":999}")" 400

echo
echo "== pagination ceiling =="
has "deep offset refused"  "$(curl -s "$B/books-list?page=100000&pageSize=100" "${P[@]}")" 'PAGE_OUT_OF_RANGE'
is  "deep offset is 400"   "$(code "$B/books-list?page=100000&pageSize=100" "${P[@]}")" 400
is  "last allowed page ok" "$(code "$B/books-list?page=101&pageSize=100" "${P[@]}")" 200
# search_books() clamps in SQL, so a direct RPC call cannot ask for more either.
is "search_books limit clamped" \
  "$(psqlq "select count(*) <= 100 from public.search_books('the', 100000, 0);")" "t"
is "search_books negative offset tolerated" \
  "$(psqlq "select count(*) >= 0 from public.search_books('the', 20, -5);")" "t"
is "search_books null args tolerated" \
  "$(psqlq "select count(*) >= 0 from public.search_books('the', null, null);")" "t"

echo
echo "== admin CMS: categories / collections / plans =="
CAT=$(curl -s -X POST "$B/admin-category-create" "${A[@]}" -d '{"label":"E2E Category"}' | sed -n 's/.*"id":"\([^"]*\)".*/\1/p')
[ -n "$CAT" ] && ok "category created" || no "category created" "an id" "empty"
has "slug derived from label" \
  "$(curl -s -X PATCH "$B/admin-category-update" "${A[@]}" -d "{\"id\":\"$CAT\",\"accent\":\"#123456\"}")" '"slug":"e2e-category"'
is "update with no fields 400"  "$(code -X PATCH "$B/admin-category-update" "${A[@]}" -d "{\"id\":\"$CAT\"}")" 400
is "delete unused category 200" "$(code -X POST "$B/admin-category-delete" "${A[@]}" -d "{\"id\":\"$CAT\"}")" 200
is "delete twice 404"           "$(code -X POST "$B/admin-category-delete" "${A[@]}" -d "{\"id\":\"$CAT\"}")" 404

COL=$(curl -s -X POST "$B/admin-collection-create" "${A[@]}" -d '{"title":"E2E Shelf","kind":"shelf"}' | sed -n 's/.*"id":"\([^"]*\)".*/\1/p')
[ -n "$COL" ] && ok "collection created" || no "collection created" "an id" "empty"
is "bad kind 400"          "$(code -X POST "$B/admin-collection-create" "${A[@]}" -d '{"title":"Bad","kind":"carousel-x"}')" 400
is "delete collection 200" "$(code -X POST "$B/admin-collection-delete" "${A[@]}" -d "{\"id\":\"$COL\"}")" 200

has "admin-plans includes inactive" "$(curl -s "$B/admin-plans" "${A[@]}")" '"entitlement_count"'
PLAN=$(curl -s -X POST "$B/admin-plan-create" "${A[@]}" -d '{"code":"e2e_plan","name":"E2E","price_cents":100}' | sed -n 's/.*"id":"\([^"]*\)".*/\1/p')
[ -n "$PLAN" ] && ok "plan created" || no "plan created" "an id" "empty"
is "duplicate code 400" "$(code -X POST "$B/admin-plan-create" "${A[@]}" -d '{"code":"e2e_plan","name":"E2E","price_cents":100}')" 400
is "bad interval 400"   "$(code -X POST "$B/admin-plan-create" "${A[@]}" -d '{"code":"e2e_plan_2","name":"E2E","price_cents":100,"interval":"fortnight"}')" 400
is "delete plan 200"    "$(code -X POST "$B/admin-plan-delete" "${A[@]}" -d "{\"id\":\"$PLAN\"}")" 200

echo
echo "== audit log attribution =="
curl -s -X PATCH "$B/admin-book-update" "${A[@]}" -d "{\"id\":\"$DRAFT\",\"genre\":\"Audited\"}" >/dev/null
AUDIT=$(curl -s "$B/admin-audit-log?entityType=books&entityId=$DRAFT" "${A[@]}")
has "book edit is logged" "$AUDIT" '"entity_type":"books"'
# The regression this guards: writes made with the service-role key used to be
# attributed to "system", which made "who published this?" unanswerable.
has "logged under the real admin, not system" "$AUDIT" "\"actor_email\":\"$EMAIL\""
is "bad entityType 400" "$(code "$B/admin-audit-log?entityType=secrets" "${A[@]}")" 400

echo
echo "== avatar upload url =="
USER_ID=$(psqlq "select id from auth.users where email='$EMAIL';")
AV=$(curl -s -X POST "$B/avatar-upload-url" "${A[@]}" -d '{"contentType":"image/png"}')
has "signed upload url minted"     "$AV" 'signedUrl'
has "path is scoped to the caller" "$AV" "\"path\":\"$USER_ID/"
is  "unsupported type 400" "$(code -X POST "$B/avatar-upload-url" "${A[@]}" -d '{"contentType":"image/gif"}')" 400

echo
echo "== RLS regression =="
# Each of these is a rule the app depends on. A failure here is a data breach,
# not a bug.
is "anon cannot read unpublished books" \
  "$(psqlq "set local role anon; select count(*) from public.books where is_published = false;")" "0"
is "no insert policy on entitlements" \
  "$(psqlq "select case when (select count(*) from pg_policies where tablename='entitlements' and cmd='INSERT') = 0 then 'blocked' else 'ALLOWED' end;")" "blocked"
is "user cannot write reading_streaks" \
  "$(psqlq "select case when has_table_privilege('authenticated','public.reading_streaks','UPDATE') then 'ALLOWED' else 'blocked' end;")" "blocked"
# A SELECT policy on storage.objects is what authorises the LIST operation.
# covers is a public bucket, so files render from /object/public/ without RLS;
# a SELECT policy there would only let anyone download the whole catalog index.
is "covers bucket cannot be enumerated by clients" \
  "$(psqlq "select case when exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and cmd='SELECT' and qual like '%covers%') then 'ALLOWED' else 'blocked' end;")" "blocked"
is "covers bucket is still public (so covers render)" \
  "$(psqlq "select public from storage.buckets where id='covers';")" "t"
is "no client SELECT policy on the pdfs bucket" \
  "$(psqlq "select case when exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and cmd='SELECT' and qual like '%pdfs%') then 'ALLOWED' else 'blocked' end;")" "blocked"
is "anon cannot execute is_admin" \
  "$(psqlq "select case when has_function_privilege('anon','public.is_admin()','EXECUTE') then 'ALLOWED' else 'blocked' end;")" "blocked"
is "anon cannot execute storage_object_exists" \
  "$(psqlq "select case when has_function_privilege('anon','public.storage_object_exists(text,text)','EXECUTE') then 'ALLOWED' else 'blocked' end;")" "blocked"
is "every public table has RLS enabled" \
  "$(psqlq "select count(*) from pg_tables t join pg_class c on c.relname = t.tablename and c.relnamespace = 'public'::regnamespace where t.schemaname='public' and not c.relrowsecurity;")" "0"
is "every SECURITY DEFINER function pins search_path" \
  "$(psqlq "select count(*) from pg_proc where pronamespace in ('public'::regnamespace,'private'::regnamespace) and prosecdef and (proconfig is null or not exists (select 1 from unnest(proconfig) cfg where cfg like 'search_path=%'));")" "0"

echo
echo "== method guards =="
is "GET profile-update 405"   "$(code "$B/profile-update" "${A[@]}")" 405
is "DELETE reading-prog 405"  "$(code -X DELETE "$B/reading-progress" "${A[@]}")" 405
is "GET wishlist-toggle 405"  "$(code "$B/wishlist-toggle" "${A[@]}")" 405
is "OPTIONS preflight 200"    "$(code -X OPTIONS "$B/books-list")" 200
is "POST books-list 405"      "$(code -X POST "$B/books-list" "${P[@]}" -H 'Content-Type: application/json' -d '{}')" 405
is "POST home-feed 405"       "$(code -X POST "$B/home-feed" "${P[@]}" -H 'Content-Type: application/json' -d '{}')" 405
is "DELETE admin-books 405"   "$(code -X DELETE "$B/admin-books" "${A[@]}")" 405
is "GET admin-audit-log 200"  "$(code "$B/admin-audit-log" "${A[@]}")" 200

echo
echo "== last-admin guard (runs last: it changes who is admin) =="
# The seed ships its own admin@ user, so the e2e admin is not the only one.
# Demote everyone else first, or the guard has nothing to guard.
psqlq "update public.profiles set role='user' where role='admin' and id <> '$USER_ID';" >/dev/null
is "only one admin remains" "$(psqlq "select count(*) from public.profiles where role='admin';")" "1"
is "cannot demote the last admin" \
  "$(code -X POST "$B/admin-set-user-role" "${A[@]}" -d "{\"userId\":\"$USER_ID\",\"role\":\"user\"}")" 409
is "the last admin is still an admin" \
  "$(psqlq "select role from public.profiles where id = '$USER_ID';")" "admin"

echo
echo "=============================="
printf "  passed: %s   failed: %s\n" "$PASS" "$FAIL"
echo "=============================="
[ "$FAIL" -eq 0 ]
